    for (const entries of bySku.values()) { entries.sort((a, b) => String(a["Month Key"]).localeCompare(String(b["Month Key"]))); for (let i = 1; i < entries.length; i += 1) { const previous = entries[i - 1], current = entries[i], difference = spreadsheetNumber(current["Cost Landed"]) - spreadsheetNumber(previous["Cost Landed"]); if (difference) revaluationRows.push({ "Month Key": current["Month Key"], Location: current.Location, "WOH SKU": current["WOH SKU"], "Prior Cost Landed": previous["Cost Landed"], "Effective Cost Landed": current["Cost Landed"], Quantity: current["Valued Quantity"], "Revaluation Gain / (Loss)": spreadsheetNumber(current["Valued Quantity"]) * difference }); } }
