    for (const row of rows.filter((row) => row.monthKey >= "2025-07" && row.inboundUnits === null)) exceptionRows.push({ "Month Key": row.monthKey, Month: row.monthLabel, Location: "Inbound to Amazon", Exception: "Saved inbound quantities not captured", "Certified Value": 0, Resolution: "Refresh this unfinalized month from Amazon or restore its saved inbound source." });
