    const sheets: Array<[string, Array<Record<string, unknown>>]> = [["Accountant Summary", accountantSummary], ["Monthly Accounting Summary", preserveFinalized("Monthly Accounting Summary", summary)], ["Inventory by Location and Stage", preserveFinalized("Inventory by Location and Stage", locationRows)], ["SKU Valuation Detail", preservedSkuRows], ["Import Cost Inputs", importRows], ["Historical SKU Costs", preserveFinalized("Historical SKU Costs", costRows)], ["ABC-to-Amazon Transfers", preserveFinalized("ABC-to-Amazon Transfers", transferRows)], ["Inventory Adjustments", adjustmentRows], ["Revaluation Gains-Losses", preserveFinalized("Revaluation Gains-Losses", revaluationRows)], ["Reconciliation Exceptions", preserveFinalized("Reconciliation Exceptions", exceptionRows)], ["Source and Audit Log", auditRows]];
