        const startDate = new Date(Date.UTC(month.year, month.monthIndex, 1));
        const endDate = new Date(Date.UTC(month.year, month.monthIndex + 1, 1) - 1);
        setAmazonInventoryHistoryProgress(`Requesting ${month.monthLabel} · month ${monthNumber + 1} of ${requestableMissingMonths.length}…`);
        const reuseOnly = cachedMonths.some((cachedMonth) => cachedMonth.monthKey === month.monthKey);
        let started = await amazonReportFetch("/api/amazon/inventory-history/start", { method: "POST", cache: "no-store", headers: { "content-type": "application/json", "x-stocklens-admin-key": ebayAdminKey }, body: JSON.stringify({ marketplaceId: amazonInventoryMarketplaceId, startDate: startDate.toISOString(), endDate: endDate.toISOString(), reuseOnly }) }, `${reuseOnly ? "Opening saved data for" : "Requesting"} ${month.monthLabel}`);
        if (!started.reportId) throw new Error(started.error || `${month.monthLabel} inventory ledger could not be requested`);
