      const key = `${clean(item.orderNumber || item.orderId)}:${cleanSku(item.wohSku)}`;
      const current = grouped.get(key) || { orderNumber: item.orderNumber || item.orderId, wohSku: item.wohSku, quantity: 0, shippingCost: 0, sourceSku: item.sku, resolvedChannel: item.resolvedChannel, sourceFile: item.sourceFile, importedAt: item.importedAt };
