    const averageRows = [...averageGroups.values()].sort((left, right) => left.wohSku.localeCompare(right.wohSku) || left.band - right.band).map((group) => ({
      "WOH SKU": group.wohSku, "Quantity Band": `${group.band}x`, "Average Shipping Cost": averageShippingValue(group.values), Samples: group.values.length,
      "Lowest Label Cost": Math.min(...group.values), "Highest Label Cost": Math.max(...group.values), "Last Rebuilt": updatedAt,
    }));
    const metadata = XLSX.utils.aoa_to_sheet([
      ["Master File", SHIPSTATION_SHIPPING_MASTER_NAME], ["Last Updated", updatedAt], ["Translation Master", SHIPSTATION_TRANSLATION_MASTER_NAME], ["Translation Master Version", translationVersion],
      ["Saved Shipping Rows", orders.length], ["Saved Item Rows", items.length], ["Resolved Item Rows", resolved.length - unresolved.length], ["Unresolved Item Rows", unresolved.length], ["Exact Single-SKU Rate Samples", exact.length],
      ["Allocation Policy", "Exact single-SKU shipments become ABC rate evidence; multi-SKU costs are retained as auditable allocations but do not replace exact rates"],
      ["Averaging Policy", "Every valid exact label is retained; average cost is recalculated separately for each WOH SKU and 1x, 2x, or 4x quantity band"],
    ]);
