    const itemSheet = XLSX.utils.json_to_sheet(items.map((item) => ({ "Order ID": item.orderId, "Order Number": item.orderNumber, "Item ID": item.itemId, SKU: item.sku, Title: item.title, Quantity: item.quantity, Marketplace: item.marketplace, "Source File": item.sourceFile, "Imported At": item.importedAt })));
    const resolvedSheet = XLSX.utils.json_to_sheet(resolved.map((item) => ({ "Order ID": item.orderId, "Order Number": item.orderNumber, "Item ID": item.itemId, "Source SKU": item.sku, Quantity: item.quantity, "Resolved Channel": item.resolvedChannel, "WOH SKU": item.wohSku, "Equivalent eBay SKU": item.ebaySku, "Equivalent Amazon SKU": item.amazonSku, "Equivalent Shopify SKU": item.shopifySku, "Mapping Status": item.mappingStatus, "Mapping Source": item.mappingSource, "Allocated Shipping Cost": item.allocatedShippingCost, "Allocation Confidence": item.allocationConfidence, "Source File": item.sourceFile, "Imported At": item.importedAt })));
    const averageSheet = XLSX.utils.json_to_sheet(averageRows);
    const rateSheet = XLSX.utils.json_to_sheet(exact.map((item) => ({ "WOH SKU": item.wohSku, Quantity: item.quantity, Band: shippingBandForQuantity(item.quantity), "Exact Label Cost": item.shippingCost, "Normalized Band Cost": item.quantity > 4 ? item.shippingCost * 4 / item.quantity : item.shippingCost, "Order Number": item.orderNumber, "Source SKU": item.sourceSku, "Resolved Channel": item.resolvedChannel, "ShipStation Source File": item.sourceFile, "Imported At": item.importedAt })));
    const unresolvedSheet = XLSX.utils.json_to_sheet(unresolved.map((item) => ({ "Order ID": item.orderId, "Order Number": item.orderNumber, "Item ID": item.itemId, SKU: item.sku, Title: item.title, Quantity: item.quantity, Status: item.mappingStatus, Reason: item.mappingSource, "Required Action": "Complete the corresponding Amazon/WOH or Shopify/WOH mapping, then reprocess these files" })));
    metadata["!cols"] = [{ wch: 32 }, { wch: 100 }];
    for (const sheet of [averageSheet, orderSheet, itemSheet, resolvedSheet, rateSheet, unresolvedSheet]) sheet["!cols"] = Array.from({ length: 18 }, () => ({ wch: 24 }));
    XLSX.utils.book_append_sheet(workbook, metadata, "Master Status"); XLSX.utils.book_append_sheet(workbook, averageSheet, "Average SKU Rates"); XLSX.utils.book_append_sheet(workbook, orderSheet, "Order Shipping Costs"); XLSX.utils.book_append_sheet(workbook, itemSheet, "Order Items"); XLSX.utils.book_append_sheet(workbook, resolvedSheet, "Resolved Order Items"); XLSX.utils.book_append_sheet(workbook, rateSheet, "Exact SKU Rate Evidence"); XLSX.utils.book_append_sheet(workbook, unresolvedSheet, "Unresolved Items");
