        await saveEbaySnapshot(ebayListings, importedAt);
        await writeDriveWorkbook(token, WOH_FOLDER_ID, EBAY_API_LISTINGS_SNAPSHOT_NAME, channelApiSnapshotWorkbook("eBay", ebayListings as unknown as Array<Record<string, unknown>>, importedAt));
