        for (const row of costRows) merged.set(clean(rowField(row, "Current Barcode", "Item Number") || wohMappingSku(row)), { ...(merged.get(clean(rowField(row, "Current Barcode", "Item Number") || wohMappingSku(row))) || {}), ...row });
        return [...merged.values()];
