    setMode("ebay"); setEbayTool("mapping"); setEbayQuickCorrectionSku(item.sku || item.listingSku); setEbayFilter(item.sku || item.listingSku); setEbayStatusFilter("All"); setSelectedEbayKeys([item.key]);
    if (!isAssemblyWorkflowStatus(item.workflowStatus)) { setEditingEbayKey(item.key); setEbayItemKeyword(item.wohSku || item.sku); }
