      const definition = [item.sku, item.itemNumber].map(cleanSku).map((key) => latestDefinitions.get(key)).find(Boolean);
      const mappingDefault = [item.sku, item.itemNumber].map(cleanSku).map((key) => mappingSourcingDefaults.get(key)).find(Boolean), sourcingType = definition?.sourcingType || mappingDefault?.sourcingType || "Buy";
