      parsed.push({ itemNumber: item.itemNumber, wohSku: item.wohSku, description: item.description, supplier: item.supplier, quantity: values.find((value) => Number.isInteger(value) && value >= 0) || 0, unitPrice: priceValues.at(-1) || 0, sourceText: line });
