  function addSelectedQuantityHighlight(output: ArrayBuffer, lastDataRow: number) {
    if (lastDataRow < 2) return new Uint8Array(output);
    const files = unzipSync(new Uint8Array(output)),
      stylesPath = "xl/styles.xml",
      sheetPath = "xl/worksheets/sheet1.xml";
    let styles = strFromU8(files[stylesPath]),
      sheetXml = strFromU8(files[sheetPath]);
    const fillMatch = styles.match(/<fills count="(\d+)">/),
      xfMatch = styles.match(/<cellXfs count="(\d+)">/);
    if (!fillMatch || !xfMatch) return new Uint8Array(output);
    const fillId = Number(fillMatch[1]),
      styleId = Number(xfMatch[1]);
    styles = styles
      .replace(
        /<fills count="\d+">/,
        `<fills count="${fillId + 1}">`,
      )
      .replace(
        "</fills>",
        '<fill><patternFill patternType="solid"><fgColor rgb="FFDDEBF7"/><bgColor indexed="64"/></patternFill></fill></fills>',
      )
      .replace(
        /<cellXfs count="\d+">/,
        `<cellXfs count="${styleId + 1}">`,
      )
      .replace(
        "</cellXfs>",
        `<xf numFmtId="0" fontId="0" fillId="${fillId}" borderId="0" xfId="0" applyFill="1"/></cellXfs>`,
      );
    sheetXml = sheetXml.replace(
      /<c r="X(\d+)"([^>]*)>/g,
      (cell, rowText: string, attributes: string) => {
        const row = Number(rowText);
        if (row < 2 || row > lastDataRow) return cell;
        return `<c r="X${rowText}"${attributes.replace(/ s="\d+"/g, "")} s="${styleId}">`;
      },
    );
    files[stylesPath] = strToU8(styles);
    files[sheetPath] = strToU8(sheetXml);
    return zipSync(files, { level: 6 });
  }
  function exportRestockPdf(sourceItems: RestockItem[]) {
    const stamp = new Date().toISOString().slice(0, 10),
      safe = (value: string) =>
        value.replace(/[^a-zA-Z0-9_-]+/g, "-").replace(/^-|-$/g, "") ||
        "supplier";
    const groups = new Map<string, RestockItem[]>();
    for (const item of sourceItems) {
      const supplier = (item.supplier || "Unspecified").trim() || "Unspecified";
      groups.set(supplier, [...(groups.get(supplier) || []), item]);
    }
    for (const [supplier, items] of [...groups.entries()].sort(([left], [right]) => left.localeCompare(right, undefined, { sensitivity: "base" }))) {
      const pdf = new jsPDF({
          orientation: "portrait",
          unit: "pt",
          format: "letter",
        }),
        width = pdf.internal.pageSize.getWidth(),
        height = pdf.internal.pageSize.getHeight(),
        margin = 38;
      let y = 82;
      const header = () => {
        pdf.setTextColor(20, 38, 53);
        pdf.setFont("helvetica", "bold");
        pdf.setFontSize(18);
        pdf.text("Restock Purchase List", margin, 32);
        pdf.setFontSize(12);
        pdf.text(supplier, margin, 49);
        pdf.setFont("helvetica", "normal");
        pdf.setFontSize(8);
        pdf.setTextColor(80, 94, 105);
        pdf.text(
          `${analysisPurchaseBasis === "with" ? "Including" : "Excluding"} safety stock - ${new Date().toLocaleString()}`,
          margin,
          63,
        );
        pdf.line(margin, 70, width - margin, 70);
      };
      header();
      for (const item of items) {
        if (y > height - 92) {
          pdf.addPage();
          header();
          y = 82;
        }
        pdf.setFont("helvetica", "bold");
        pdf.setFontSize(9);
        pdf.setTextColor(20, 38, 53);
        pdf.text(`Item: ${item.itemNumber}`, margin, y);
        pdf.text(`SKU: ${item.sku || "-"}`, margin, y + 14);
        pdf.setFontSize(12);
        pdf.text(`Qty: ${item.purchaseQuantity}`, width - 112, y + 14);
        pdf.addImage(
          barcodeImage(item.itemNumber),
          "PNG",
          width - 258,
          y - 9,
          132,
          46,
        );
        pdf.setDrawColor(220, 226, 222);
        pdf.line(margin, y + 51, width - margin, y + 51);
        y += 64;
      }
      pdf.setFont("helvetica", "normal");
      pdf.setFontSize(8);
      pdf.setTextColor(90, 100, 106);
      pdf.text(
        `${items.length} items - ${items.reduce((sum, item) => sum + item.purchaseQuantity, 0)} units`,
        margin,
        height - 22,
      );
      downloadBlob(
        pdf.output("blob"),
        `restock-${safe(supplier)}-${stamp}.pdf`,
      );
    }
  }
  function parsePullMaster(buffer: ArrayBuffer) {
    const workbook = XLSX.read(buffer, { type: "array" }),
      sheet = workbook.Sheets[workbook.SheetNames[0]],
      records = XLSX.utils.sheet_to_json<Record<string, unknown>>(sheet, {
        defval: "",
        raw: false,
      }),
      items: PullMasterItem[] = records
        .map((row) => ({
          barcode: String(row["Item Number"] || "").trim(),
          sku: String(row.SKU || "").trim(),
          description: String(row.Description || "").trim(),
          totalPulled: Number(row["Total Pulled"] || 0),
          lastPull: String(row["Last Pull Date Time"] || ""),
          status:
            String(row["Count Status"] || "Pending") === "Counted"
              ? "Counted"
              : "Pending",
          currentQuantity: Number(row["Last Current Quantity"] || 0),
          countedQuantity: Number(row["Last Counted Quantity"] || 0),
          adjustment: Number(row["Last Adjustment"] || 0),
          lastCount: String(row["Last Count Date Time"] || ""),
        }))
        .filter((item) => item.barcode);
    return { workbook, sheet, items };
  }
