  async function downloadInventoryMovesThroughCentralConnection(token: string) {
    const response = await fetch("/api/inventory/current-ledger", {
      headers: { Authorization: `Bearer ${token}` },
      cache: "no-store",
    });
    if (!response.ok) {
      const data = await response.json().catch(() => ({}));
      throw new Error(data?.error || `The current inventory ledger could not be loaded (HTTP ${response.status}).`);
    }
    const encodedName = response.headers.get("x-stocklens-source-name") || encodeURIComponent(INVENTORY_MOVES_FILE_NAME);
    let name = INVENTORY_MOVES_FILE_NAME;
    try { name = decodeURIComponent(encodedName); } catch { name = INVENTORY_MOVES_FILE_NAME; }
    return {
      file: { id: "central-drive-current-ledger", name, modifiedTime: response.headers.get("x-stocklens-source-modified") || "" },
      buffer: await response.arrayBuffer(),
    };
  }
  async function downloadLatestInventoryMovesFileUncached(token: string) {
    try {
      const file = await findLatestInventoryMovesFile(token);
      const buffer = await downloadDriveFile(token, file.id, `${file.name} could not be opened`);
      return { file, buffer };
    } catch {
      return downloadInventoryMovesThroughCentralConnection(token);
    }
  }

  function downloadLatestInventoryMovesFile(token: string) {
    if (!sessionInventoryMovesPromiseRef.current) {
      sessionInventoryMovesPromiseRef.current = downloadLatestInventoryMovesFileUncached(token).catch((error) => {
        sessionInventoryMovesPromiseRef.current = null;
        throw error;
      });
    }
    return sessionInventoryMovesPromiseRef.current;
  }

  async function loadInventoryMovesBuffer(token: string) {
    return (await downloadLatestInventoryMovesFile(token)).buffer;
  }
  async function getDriveFileById(token: string, fileId: string, expectedName: string) {
    const response = await fetch(`https://www.googleapis.com/drive/v3/files/${fileId}?fields=id,name,webViewLink,modifiedTime,trashed`, {
      headers: { Authorization: `Bearer ${token}`, "Cache-Control": "no-cache" },
      cache: "no-store",
    });
    const data = await response.json().catch(() => ({}));
    if (!response.ok) throw new Error(data?.error?.message || `${expectedName} could not be opened by its permanent Drive ID`);
    if (data.trashed) throw new Error(`${expectedName} is in Google Drive trash`);
    return data as { id: string; name: string; webViewLink?: string; modifiedTime?: string };
  }
  const driveBackupFolderCache = new Map<string, string>();
  async function ensureDriveFolder(token: string, parentId: string, name: string) {
    const cacheKey = `${parentId}:${name}`;
    const cached = driveBackupFolderCache.get(cacheKey);
    if (cached) return cached;
    const q = `'${parentId}' in parents and name='${name.replaceAll("'", "\\'")}' and mimeType='application/vnd.google-apps.folder' and trashed=false`;
    const lookup = await fetch(`https://www.googleapis.com/drive/v3/files?q=${encodeURIComponent(q)}&fields=files(id,name)&pageSize=10`, { headers: { Authorization: `Bearer ${token}` }, cache: "no-store" });
    const lookupData = await lookup.json().catch(() => ({}));
    if (!lookup.ok) throw new Error(lookupData?.error?.message || `${name} backup folder could not be found`);
    let folderId = String(lookupData.files?.[0]?.id || "");
    if (!folderId) {
      const create = await fetch("https://www.googleapis.com/drive/v3/files?fields=id,name", {
        method: "POST", headers: { Authorization: `Bearer ${token}`, "Content-Type": "application/json" },
        body: JSON.stringify({ name, mimeType: "application/vnd.google-apps.folder", parents: [parentId] }),
      });
      const createData = await create.json().catch(() => ({}));
      if (!create.ok || !createData.id) throw new Error(createData?.error?.message || `${name} backup folder could not be created`);
      folderId = String(createData.id);
    }
    driveBackupFolderCache.set(cacheKey, folderId);
    return folderId;
  }
  function driveBackupCategory(name: string) {
    const value = name.toLowerCase();
    if (/mapping|map-|equivalent/.test(value)) return "02 - Mapping Masters";
    if (/abc|analysis|forecast|profit|reconciliation|shipping-cost|purchasing|vendor-quote/.test(value)) return "03 - Analysis Results";
    if (/api|cache|snapshot|transaction|order|shipping-report/.test(value)) return "04 - API Data Pulls";
    if (/woh|inventory adj|location master|source/.test(value)) return "01 - Source Data";
    return "05 - Operational Reports";
  }
  function readableBackupName(name: string, versionDate: string) {
    const date = new Date(versionDate);
    const stamp = Number.isNaN(date.getTime()) ? new Date().toISOString() : date.toISOString();
    return `${stamp.slice(0, 19).replace("T", " ").replaceAll(":", "-")} - ${name}`;
  }
  async function backupDriveFile(token: string, fileId: string, name: string, versionDate: string, onlyOnce = false) {
    if (!fileId || name.startsWith(`${DRIVE_BACKUP_ROOT_NAME}/`)) return;
    const rootId = await ensureDriveFolder(token, WOH_FOLDER_ID, DRIVE_BACKUP_ROOT_NAME);
    const categoryId = await ensureDriveFolder(token, rootId, driveBackupCategory(name));
    const backupName = readableBackupName(name, versionDate);
    if (onlyOnce && await findDriveFileInFolder(token, categoryId, backupName)) return;
    const response = await fetch(`https://www.googleapis.com/drive/v3/files/${fileId}/copy?fields=id,name,webViewLink,createdTime`, {
      method: "POST", headers: { Authorization: `Bearer ${token}`, "Content-Type": "application/json" },
      body: JSON.stringify({ name: backupName, parents: [categoryId] }),
    });
    const data = await response.json().catch(() => ({}));
    if (!response.ok) throw new Error(data?.error?.message || `${name} was updated, but its Google Drive backup could not be created`);
  }
  async function backupSourceFileVersion(token: string, file: { id: string; name: string; modifiedTime?: string }) {
    await attemptDriveBackup(token, file.id, file.name, file.modifiedTime || new Date().toISOString(), true);
  }
  async function backupSourceFileById(token: string, fileId: string, fallbackName: string) {
    const response = await fetch(`https://www.googleapis.com/drive/v3/files/${fileId}?fields=id,name,modifiedTime`, { headers: { Authorization: `Bearer ${token}` }, cache: "no-store" });
    const data = await response.json().catch(() => ({}));
    if (!response.ok) throw new Error(data?.error?.message || `${fallbackName} backup metadata could not be read`);
    await backupSourceFileVersion(token, { id: fileId, name: String(data.name || fallbackName), modifiedTime: String(data.modifiedTime || "") });
  }
  async function attemptDriveBackup(token: string, fileId: string, name: string, versionDate: string, onlyOnce = false) {
    try {
      await backupDriveFile(token, fileId, name, versionDate, onlyOnce);
      return true;
    } catch {
      // Warehouse users may be able to read or update operational files without
      // permission to create backup folders. Their primary workflow must continue;
      // an owner/editor run will create the same versioned backup later.
      return false;
    }
  }
  async function listHistoricalWohFiles(token: string) {
    const files: Array<{ id: string; name: string; modifiedTime?: string; createdTime?: string; size?: string; mimeType?: string }> = [];
    const pendingFolders = [WOH_FOLDER_ID];
    const visitedFolders = new Set<string>();
    while (pendingFolders.length) {
      const folderId = pendingFolders.shift()!;
      if (visitedFolders.has(folderId)) continue;
      visitedFolders.add(folderId);
      let pageToken = "";
      do {
        const q = `'${folderId}' in parents and trashed=false`;
        const params = new URLSearchParams({
          q,
          fields: "nextPageToken,files(id,name,modifiedTime,createdTime,size,mimeType)",
          orderBy: "modifiedTime asc",
          pageSize: "100",
        });
        if (pageToken) params.set("pageToken", pageToken);
        const response = await fetch(`https://www.googleapis.com/drive/v3/files?${params}`, {
          headers: { Authorization: `Bearer ${token}` },
          cache: "no-store",
        });
        const data = await response.json().catch(() => ({}));
        if (!response.ok)
          throw new Error(data?.error?.message || "Historical WOH files could not be listed");
        for (const file of data.files || []) {
          if (file.mimeType === "application/vnd.google-apps.folder") pendingFolders.push(file.id);
          else files.push(file);
        }
        pageToken = data.nextPageToken || "";
      } while (pageToken);
    }
    return files.filter((file) =>
      file.id !== WOH_FILE_ID &&
      /\.(xlsm|xlsx|xls)$/i.test(file.name) &&
      !/^stocklens-/i.test(file.name) &&
      /^(WOH)(?:\s|_|-|\.)/i.test(file.name),
    );
  }
  async function writeDriveWorkbook(token: string, folderId: string, name: string, workbook: XLSX.WorkBook, permanentFileId?: string) {
    const output = XLSX.write(workbook, { bookType: "xlsx", type: "array" }) as ArrayBuffer;
    const existing = permanentFileId
      ? await getDriveFileById(token, permanentFileId, name)
      : await findDriveFileInFolder(token, folderId, name);
    if (!existing) {
      return saveNewDriveFile(token, name, "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet", new Blob([output]), folderId);
    }
    const response = await fetch(`https://www.googleapis.com/upload/drive/v3/files/${existing.id}?uploadType=media&fields=id,name,webViewLink`, {
      method: "PATCH",
      headers: { Authorization: `Bearer ${token}`, "Content-Type": "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet" },
      body: output,
    });
    const data = await response.json().catch(() => ({}));
    if (!response.ok) throw new Error(data?.error?.message || `${name} could not be updated`);
    await attemptDriveBackup(token, existing.id, name, new Date().toISOString());
    return { ...existing, ...data };
  }
  const historicalDateFromName = (name: string, fallback: string) => {
    const match = name.match(/(?:^|\s)(\d{1,2})[-_](\d{1,2})[-_](\d{2,4})(?:\D|$)/);
    if (!match) return fallback.slice(0, 10);
    const year = Number(match[3]) < 100 ? 2000 + Number(match[3]) : Number(match[3]);
    const date = new Date(Date.UTC(year, Number(match[1]) - 1, Number(match[2])));
    return Number.isNaN(date.getTime()) ? fallback.slice(0, 10) : date.toISOString().slice(0, 10);
  };
  const historicalNumber = (value: unknown) => {
    const text = String(value ?? "").trim();
    if (!text) return null;
    const negative = /^\(.*\)$/.test(text);
    const parsed = Number(text.replace(/[,$()\s]/g, ""));
    return Number.isFinite(parsed) ? (negative ? -parsed : parsed) : null;
  };
  function extractWohCostObservations(
    buffer: ArrayBuffer,
    source: Omit<WohHistorySource, "rowCount" | "status" | "note">,
  ) {
    const workbook = XLSX.read(buffer, { type: "array" });
    let selected: { sheet: XLSX.WorkSheet; headerRow: number; score: number } | null = null;
    for (const sheetName of workbook.SheetNames) {
      const sheet = workbook.Sheets[sheetName];
      const preview = XLSX.utils.sheet_to_json<Array<unknown>>(sheet, { header: 1, defval: "", raw: false }).slice(0, 12);
      preview.forEach((row, index) => {
        const headers = row.map((value) => clean(String(value || "")));
        const score = Number(headers.includes("currentbarcode")) * 4 + Number(headers.includes("sku")) * 3 + Number(headers.includes("costchina")) * 3 + Number(headers.includes("unitcostlanded")) * 2 + Number(headers.includes("supplier"));
        if (score >= 6 && (!selected || score > selected.score)) selected = { sheet, headerRow: index, score };
      });
    }
    if (!selected) throw new Error("No worksheet with recognizable WOH item and cost columns was found");
    const records = XLSX.utils.sheet_to_json<Record<string, unknown>>(selected.sheet, { range: selected.headerRow, defval: "", raw: false });
    const observations: WohCostObservation[] = [];
    for (const record of records) {
      const normalized = new Map(Object.keys(record).map((key) => [clean(key), record[key]]));
      const value = (...aliases: string[]) => {
        for (const alias of aliases) {
          const found = normalized.get(clean(alias));
          if (found !== undefined && String(found).trim()) return String(found).trim();
        }
        return "";
      };
      const itemNumber = value("Current Barcode", "Item Number", "Item ID", "Barcode");
      const sku = value("SKU", "sku");
      if (!itemNumber && !sku) continue;
      observations.push({
        itemNumber,
        sku,
        description: value("Description", "Item Description"),
        supplier: value("Supplier", "Vendor"),
        costChina: historicalNumber(value("Cost China", "China Cost")),
        costLanded: historicalNumber(value("Unit Cost Landed", "Cost Landed", "Landed Cost")),
        fnsku: value("FNSKU", "fnsku"),
        fnsku2: value("FNSKU2", "FNSKU 2", "fnsku2"),
        amazonSku: value("Amazon SKU", "AMZ SKU"),
        sourceDate: source.sourceDate,
        sourceName: source.sourceName,
        sourceId: source.sourceId,
        revisionId: source.revisionId,
        sourceType: source.sourceType,
        method: "Observed",
        confidence: "High",
      });
    }
    return observations;
  }
  function historicalWohCostWorkbook(observations: WohCostObservation[], sources: WohHistorySource[]) {
    const workbook = XLSX.utils.book_new();
    const createdAt = new Date().toISOString();
    const readme = XLSX.utils.aoa_to_sheet([
      ["StockLens Historical WOH Costs"],
      ["Generated At", createdAt],
      ["Purpose", "Observed historical Cost China and Cost Landed values from retained WOH revisions and standalone WOH snapshots."],
      ["Important", "Observed values are never replaced with estimates. Future estimated rows must be separately labeled with their method and confidence."],
      ["Observed Rows", observations.length],
      ["Imported Sources", sources.filter((source) => source.status === "Imported").length],
      ["Failed or Skipped Sources", sources.filter((source) => source.status !== "Imported").length],
    ]);
    readme["!cols"] = [{ wch: 28 }, { wch: 110 }];
    XLSX.utils.book_append_sheet(workbook, readme, "README");

    const observedHeaders = ["Item Number", "SKU", "Description", "Supplier", "Cost China", "Cost Landed", "FNSKU", "FNSKU2", "Amazon SKU", "Effective Date", "Source Name", "Source Type", "Source File ID", "Revision ID", "Method", "Confidence"];
    const observedRows = observations
      .slice()
      .sort((a, b) => a.sourceDate.localeCompare(b.sourceDate) || (a.itemNumber || a.sku).localeCompare(b.itemNumber || b.sku, undefined, { numeric: true }))
      .map((row) => [row.itemNumber, row.sku, row.description, row.supplier, row.costChina ?? "", row.costLanded ?? "", row.fnsku, row.fnsku2, row.amazonSku, row.sourceDate, row.sourceName, row.sourceType, row.sourceId, row.revisionId, row.method, row.confidence]);
    const observedSheet = XLSX.utils.aoa_to_sheet([observedHeaders, ...observedRows]);
    observedSheet["!cols"] = observedHeaders.map((header) => ({ wch: /Description/.test(header) ? 42 : /Source Name/.test(header) ? 34 : /ID/.test(header) ? 28 : 18 }));
    observedSheet["!autofilter"] = { ref: `A1:P${Math.max(1, observedRows.length + 1)}` };
    for (let row = 2; row <= observedRows.length + 1; row++) {
      if (observedSheet[`E${row}`]) observedSheet[`E${row}`].z = '"$"#,##0.0000';
      if (observedSheet[`F${row}`]) observedSheet[`F${row}`].z = '"$"#,##0.0000';
    }
    XLSX.utils.book_append_sheet(workbook, observedSheet, "Observed Costs");

    const byItem = new Map<string, WohCostObservation[]>();
    for (const row of observations) {
      const key = clean(row.itemNumber || row.sku);
      if (!key) continue;
      byItem.set(key, [...(byItem.get(key) || []), row]);
    }
    const changes: Array<Array<string | number>> = [];
    for (const itemRows of byItem.values()) {
      itemRows.sort((a, b) => a.sourceDate.localeCompare(b.sourceDate));
      let prior: WohCostObservation | null = null;
      for (const row of itemRows) {
        const chinaChanged = prior && row.costChina !== null && prior.costChina !== null && row.costChina !== prior.costChina;
        const landedChanged = prior && row.costLanded !== null && prior.costLanded !== null && row.costLanded !== prior.costLanded;
        if (prior && (chinaChanged || landedChanged)) changes.push([
          row.itemNumber, row.sku, row.supplier, prior.sourceDate, row.sourceDate,
          prior.costChina ?? "", row.costChina ?? "", chinaChanged ? (row.costChina! - prior.costChina!) : "",
          prior.costLanded ?? "", row.costLanded ?? "", landedChanged ? (row.costLanded! - prior.costLanded!) : "",
          prior.sourceName, row.sourceName,
        ]);
        prior = row;
      }
    }
    const changeHeaders = ["Item Number", "SKU", "Supplier", "Prior Date", "New Date", "Prior Cost China", "New Cost China", "China Change", "Prior Cost Landed", "New Cost Landed", "Landed Change", "Prior Source", "New Source"];
    const changeSheet = XLSX.utils.aoa_to_sheet([changeHeaders, ...changes]);
    changeSheet["!cols"] = changeHeaders.map((header) => ({ wch: /Source/.test(header) ? 34 : 18 }));
    changeSheet["!autofilter"] = { ref: `A1:M${Math.max(1, changes.length + 1)}` };
    for (let row = 2; row <= changes.length + 1; row++) for (const column of ["F", "G", "H", "I", "J", "K"]) if (changeSheet[`${column}${row}`]) changeSheet[`${column}${row}`].z = '"$"#,##0.0000';
    XLSX.utils.book_append_sheet(workbook, changeSheet, "Cost Changes");

    const sourceHeaders = ["Source Date", "Source Name", "Source Type", "Source File ID", "Revision ID", "Modified Time", "Keep Forever", "Rows Imported", "Status", "Note"];
    const sourceRows = sources.slice().sort((a, b) => a.sourceDate.localeCompare(b.sourceDate)).map((source) => [source.sourceDate, source.sourceName, source.sourceType, source.sourceId, source.revisionId, source.modifiedTime, source.keepForever ? "Yes" : "No", source.rowCount, source.status, source.note]);
    const sourceSheet = XLSX.utils.aoa_to_sheet([sourceHeaders, ...sourceRows]);
    sourceSheet["!cols"] = sourceHeaders.map((header) => ({ wch: header === "Note" ? 60 : header.includes("Name") ? 34 : header.includes("ID") ? 28 : 18 }));
    sourceSheet["!autofilter"] = { ref: `A1:J${Math.max(1, sourceRows.length + 1)}` };
    XLSX.utils.book_append_sheet(workbook, sourceSheet, "Sources");

    const missingRows = observations.filter((row) => row.costChina === null).map((row) => [row.itemNumber, row.sku, row.description, row.supplier, row.sourceDate, row.sourceName, "Missing observed Cost China; estimate only after checking first inventory activity and comparable vendor/SKU evidence."]);
    const missingSheet = XLSX.utils.aoa_to_sheet([["Item Number", "SKU", "Description", "Supplier", "Effective Date", "Source Name", "Review Note"], ...missingRows]);
    missingSheet["!cols"] = [{ wch: 18 }, { wch: 24 }, { wch: 42 }, { wch: 24 }, { wch: 16 }, { wch: 34 }, { wch: 90 }];
    missingSheet["!autofilter"] = { ref: `A1:G${Math.max(1, missingRows.length + 1)}` };
    XLSX.utils.book_append_sheet(workbook, missingSheet, "Missing Cost Review");
    return workbook;
  }
  function ebayMappingMasterWorkbook(mappings: EbayMapping[], importedAt: string) {
    const headers = ["eBay Listing Key", "eBay Listing ID", "eBay SKU", "Title", "Variation", "eBay Listing Status", "Mapping Status", "Assembly Review", "WOH SKU", "WOH Description", "Knowledge Source", "Decision Locked"];
    for (let index = 1; index <= 10; index++) headers.push(`Subassy SKU ${index}`, `Qty ${index}`, `Subassy WOH SKU ${index}`, `Subassy WOH Description ${index}`);
    headers.push("Assembly Labor Cost", "eBay File Imported At", "Drive Master Updated At");
    const updatedAt = new Date().toISOString();
    const data = mappings.map((mapping) => {
      const row: Array<string | number> = [mapping.key, mapping.listingId, mapping.sku || mapping.listingSku, mapping.title, mapping.variation, mapping.status, mapping.workflowStatus, isAssemblyWorkflowStatus(mapping.workflowStatus) ? (mapping.assemblyConfirmed ? "Confirmed" : "Unconfirmed") : "", mapping.wohSku, mapping.wohDescription, mapping.knowledgeSource || "", ebayMappingHasUserDecision(mapping) ? "Yes" : "No"];
      for (let index = 0; index < 10; index++) {
        const component = mapping.assemblyComponents[index];
        row.push(component?.sku || "", component?.quantity ?? "", component?.wohSku || "", component?.wohDescription || "");
      }
      row.push(isAssemblyWorkflowStatus(mapping.workflowStatus) ? (mapping.assemblyLaborCost ?? 2) : 0, importedAt, updatedAt);
      return row;
    });
    const sheet = XLSX.utils.aoa_to_sheet([headers, ...data]);
    sheet["!cols"] = headers.map((header) => ({ wch: header.includes("Title") || header.includes("Description") ? 42 : header.includes("Key") ? 34 : 20 }));
    sheet["!autofilter"] = { ref: `A1:${XLSX.utils.encode_col(headers.length - 1)}${data.length + 1}` };
    const workbook = XLSX.utils.book_new();
    XLSX.utils.book_append_sheet(workbook, sheet, "eBay to WOH Master");
    return workbook;
  }
  function ebayMappingHistoryWorkbook(changes: EbayMappingHistory[]) {
    const headers = ["Change ID", "Session ID", "Session Status", "Session Started", "Session Ended", "eBay Listing Key", "Action", "Previous Values", "New Values", "Changed At"];
    const data = changes.map((change) => [change.id, change.session_id, change.session_status || "", change.started_at || "", change.ended_at || "", change.listing_key, change.action, change.old_value, change.new_value, change.changed_at]);
    const sheet = XLSX.utils.aoa_to_sheet([headers, ...data]);
    sheet["!cols"] = [{ wch: 12 }, { wch: 38 }, { wch: 16 }, { wch: 24 }, { wch: 24 }, { wch: 40 }, { wch: 20 }, { wch: 60 }, { wch: 60 }, { wch: 24 }];
    sheet["!autofilter"] = { ref: `A1:J${data.length + 1}` };
    const workbook = XLSX.utils.book_new();
    XLSX.utils.book_append_sheet(workbook, sheet, "Mapping Session History");
    return workbook;
  }
  function ebayItemCostMasterWorkbook(mappings: EbayMapping[], wohRows: Row[], updatedAt: string) {
    const headers = ["eBay Listing ID", "eBay SKU", "Title", "Mapping Status", "Cost Type", "WOH Component SKU", "Component Description", "Component Quantity", "Unit Landed Cost", "Extended Component Cost", "Labor Cost", "Total eBay Item Cost", "Updated At"];
    const data: Array<Array<string | number>> = [];
    for (const mapping of mappings) {
      const sku = mapping.sku || mapping.listingSku || "";
      const components = isAssemblyWorkflowStatus(mapping.workflowStatus)
        ? mapping.assemblyComponents.map((component) => ({ sku: component.wohSku || component.sku, quantity: assemblyQuantity(component.quantity) }))
        : mapping.wohSku ? [{ sku: mapping.wohSku, quantity: 1 }] : [];
      const resolved = components.map((component) => {
        const row = findWohByReference(wohRows, component.sku);
        const unitCost = row ? spreadsheetNumber(rowField(row, "Unit Cost Landed", "Cost Landed")) : 0;
        return { ...component, row, unitCost, extended: unitCost * component.quantity };
      });
      const labor = isAssemblyWorkflowStatus(mapping.workflowStatus) ? (mapping.assemblyLaborCost ?? 2) : 0;
      const total = resolved.reduce((sum, component) => sum + component.extended, 0) + labor;
      for (const component of resolved) data.push([mapping.listingId, sku, mapping.title, mapping.workflowStatus, "Component", component.sku, component.row ? rowField(component.row, "Description", "Item Description") : "", component.quantity, component.unitCost, component.extended, 0, total, updatedAt]);
      if (labor) data.push([mapping.listingId, sku, mapping.title, mapping.workflowStatus, "Labor", "", "Standard assembly labor", 1, 0, 0, labor, total, updatedAt]);
      if (!resolved.length) data.push([mapping.listingId, sku, mapping.title, mapping.workflowStatus, "Unresolved", "", "No costed WOH component", 0, 0, 0, 0, 0, updatedAt]);
    }
    const sheet = XLSX.utils.aoa_to_sheet([headers, ...data]);
    sheet["!cols"] = headers.map((header) => ({ wch: /Title|Description/.test(header) ? 42 : 22 }));
    sheet["!autofilter"] = { ref: `A1:M${data.length + 1}` };
    const workbook = XLSX.utils.book_new();
    XLSX.utils.book_append_sheet(workbook, sheet, "eBay Item Cost Master");
    return workbook;
  }
  async function syncEbayMappingDriveFiles(token: string, mappings: EbayMapping[], changes: EbayMappingHistory[], importedAt: string, progress: (key: EbayMappingProcessKey, status: EbayMappingProcessStatus, detail?: string, error?: string) => void = () => {}) {
    progress("channelMaster", "active", "Preparing Shopify, channel-master, and WOH inputs");
    const shopifyResponse = await fetch("/api/shopify/mappings", { cache: "no-store", headers: { "x-stocklens-admin-key": ebayAdminKey } });
    const shopifyData = await shopifyResponse.json().catch(() => null) as { mappings?: Array<Record<string, unknown>> } | null;
    if (!shopifyResponse.ok) {
      const message = "Saved Shopify mappings could not be included in the permanent channel master";
      progress("channelMaster", "error", undefined, message); throw new Error(message);
    }
    const savedShopifyItems: ShopifyMapping[] = (shopifyData?.mappings || []).map((mapping) => {
      const parsed = parsedSavedAssembly(String(mapping.assembly_components || "[]"));
      return {
        variantId: String(mapping.variant_id || ""), productId: String(mapping.product_id || ""), key: String(mapping.variant_id || ""),
        sku: String(mapping.shopify_sku || ""), title: "", productTitle: "", productStatus: "Saved", barcode: "",
        wohSku: String(mapping.woh_sku || ""), wohDescription: "", matchStatus: mapping.woh_sku ? "Manual" : "Unmatched",
        workflowStatus: String(mapping.workflow_status || "Unmatched") as EbayWorkflowStatus,
        confirmed: Number(mapping.confirmed || 0) === 1, assemblyConfirmed: parsed.confirmed,
        assemblyComponents: parsed.components, knowledgeSource: String(mapping.knowledge_source || "Saved Shopify mapping"),
      };
    });
    const currentChannelMaster = await loadChannelMappingMasterRows(token).catch(() => null);
    const masterShopifyItems = shopifyMappings.length ? shopifyMappings : currentChannelMaster?.shopifyMappings?.length ? currentChannelMaster.shopifyMappings : savedShopifyItems;
    let wohRows: Row[];
    try { wohRows = rows.some((row) => rowField(row, "Current Barcode")) ? rows : await loadWohRows(token); }
    catch (error) { const message = error instanceof Error ? error.message : "WOH data could not be loaded for the channel master"; progress("channelMaster", "error", undefined, message); throw error; }
    const trackedWrite = async <T,>(key: EbayMappingProcessKey, task: () => Promise<T>, successDetail: string) => {
      progress(key, "active");
      try { const result = await task(); progress(key, "done", successDetail); return result; }
      catch (error) { const message = error instanceof Error ? error.message : `${successDetail} failed`; progress(key, "error", undefined, message); throw error; }
    };
    const results = await Promise.allSettled([
      trackedWrite("ebayMaster", () => writeDriveWorkbook(token, EBAY_MAPPING_FOLDER_ID, EBAY_MAPPING_MASTER_NAME, ebayMappingMasterWorkbook(mappings, importedAt), EBAY_MAPPING_MASTER_FILE_ID), `${mappings.length.toLocaleString()} mappings written to ${EBAY_MAPPING_MASTER_NAME}`),
      trackedWrite("historyMaster", () => writeDriveWorkbook(token, EBAY_MAPPING_FOLDER_ID, EBAY_MAPPING_HISTORY_NAME, ebayMappingHistoryWorkbook(changes)), `${changes.length.toLocaleString()} history records written to ${EBAY_MAPPING_HISTORY_NAME}`),
      trackedWrite("channelMaster", async () => {
        const master = await syncChannelMappingMaster(token, masterShopifyItems, mappings, wohRows);
        await writeDriveWorkbook(token, EBAY_MAPPING_FOLDER_ID, EBAY_ITEM_COST_MASTER_NAME, ebayItemCostMasterWorkbook(mappings, wohRows, importedAt));
        return master;
      }, `${CHANNEL_MAPPING_MASTER_NAME}, ${SHIPSTATION_TRANSLATION_MASTER_NAME}, and ${EBAY_ITEM_COST_MASTER_NAME} rebuilt`),
    ]);
    const failures = results.filter((result): result is PromiseRejectedResult => result.status === "rejected");
    if (failures.length) throw new Error(failures.map((failure) => failure.reason instanceof Error ? failure.reason.message : String(failure.reason)).join(" · "));
    const channelMaster = results[2].status === "fulfilled" ? results[2].value : null;
    progress("verify", "active");
    try {
      await Promise.all([
        getDriveFileById(token, EBAY_MAPPING_MASTER_FILE_ID, EBAY_MAPPING_MASTER_NAME),
        getDriveFileById(token, CHANNEL_MAPPING_MASTER_FILE_ID, CHANNEL_MAPPING_MASTER_NAME),
        getDriveFileById(token, SHIPSTATION_TRANSLATION_MASTER_FILE_ID, SHIPSTATION_TRANSLATION_MASTER_NAME),
      ]);
      progress("verify", "done", "eBay, channel, and ShipStation permanent files reopened successfully");
    } catch (error) {
      const message = error instanceof Error ? error.message : "Permanent Drive files could not be verified";
      progress("verify", "error", undefined, message); throw error;
    }
    if (!channelMaster) throw new Error("The channel mapping master did not return a version");
    setMappingMasterVersionDate(channelMaster.versionDate);
    return channelMaster;
  }
  async function syncEbayMappingDriveFilesNow() {
    const startedAt = beginEbayMappingProcess("Synchronize permanent eBay/WOH files", "sync", "drive");
    (["admin", "snapshot", "build", "rules"] as EbayMappingProcessKey[]).forEach((key) => updateEbayMappingProcessStep(key, "skipped", "Not required for a permanent-master retry"));
    try {
      const token = await getAccessToken();
      updateEbayMappingProcessStep("drive", "done", "Google Drive authorization is active");
      updateEbayMappingProcessStep("inputs", "active", "Opening the complete mapping history before writing files");
      const response = await fetch("/api/ebay/mapping-history", { cache: "no-store", headers: { "x-stocklens-admin-key": ebayAdminKey } });
      const data = await response.json().catch(() => null) as { changes?: EbayMappingHistory[]; error?: string } | null;
      if (!response.ok) { if (response.status === 403) expireEbayAdminSession(); throw new Error(data?.error || "Mapping history could not be opened"); }
      updateEbayMappingProcessStep("inputs", "done", `${(data?.changes || []).length.toLocaleString()} history records and ${ebayMappings.length.toLocaleString()} mappings ready`);
      const master = await syncEbayMappingDriveFiles(token, ebayMappings, data?.changes || [], ebayImportedAt, updateEbayMappingProcessStep);
      setNotice(`Permanent eBay/WOH mapping master synchronized · version ${new Date(master.versionDate).toLocaleString()}`);
      finishEbayMappingProcess(startedAt);
      return true;
    } catch (error) {
      const message = error instanceof Error ? error.message : "Google Drive mapping files could not be synchronized";
      failActiveEbayMappingProcess(message); setNotice(message); finishEbayMappingProcess(startedAt);
      return false;
    }
  }
  function ruleLabComponents(value: unknown): EbayAssemblyComponent[] {
    if (!Array.isArray(value)) return [];
    return value.slice(0, 10).map((entry) => {
      const tuple = Array.isArray(entry) ? entry : [];
      const wohSku = String(tuple[0] || "").trim();
      const wohRow = findWohByReference(rows, wohSku);
      return {
        sku: String(tuple[3] || wohSku).trim(),
        quantity: assemblyQuantity(tuple[1], 0),
        wohSku: wohRow ? wohMappingSku(wohRow) : wohSku,
        wohDescription: wohRow?.description || "",
        suggested: false,
        suggestionSource: String(tuple[2] || "Imported from completed Rule Lab review"),
      };
    });
  }
  async function importCompletedRuleLabExport(file: File) {
    setRuleLabImporting(true);
    setRuleLabImportMessage("Reading and validating the completed Rule Lab decisions…");
    try {
      if (!ebayMappings.length) throw new Error("Open the existing eBay mapping master before importing the completed review.");
      if (ebaySession?.status !== "active") throw new Error("Start or resume an eBay mapping session before importing the completed review.");
      const payload = JSON.parse(await file.text()) as RuleLabExport;
      if (!Array.isArray(payload.sourceItems) || !payload.sourceItems.length)
        throw new Error("This is an older Rule Lab export. Re-open Rule Lab and export again so the file includes source listing identities.");
      const sourceById = new Map(payload.sourceItems.map((item) => [item.id, item]));
      const decisions = new Map<string, { status: EbayWorkflowStatus; wohSku?: string; components?: EbayAssemblyComponent[]; source: string }>();
      for (const direct of payload.directMatches || [])
        decisions.set(direct.id, { status: "Exact Matches", wohSku: direct.wohSku, source: "Rule Lab verified literal WOH match" });
      for (const assembly of payload.autoConfirmedAssemblies || [])
        decisions.set(assembly.id, { status: "Assy Auto Matched", components: ruleLabComponents(assembly.components), source: "Rule Lab non-contradicting automatic assembly evidence" });
      for (const [id, staged] of Object.entries(payload.stagedDecisions || {})) {
        if (staged.status === "Deferred") decisions.set(id, { status: "Deferred", source: "Deferred in completed Rule Lab review" });
        else if (staged.status === "Confirmed proposal") decisions.set(id, { status: "Assemblies", components: ruleLabComponents(staged.components), source: "User-confirmed Rule Lab assembly" });
      }
      const missingDecisions = payload.sourceItems.filter((item) => !decisions.has(item.id));
      if (missingDecisions.length)
        throw new Error(`${missingDecisions.length} exported item${missingDecisions.length === 1 ? " is" : "s are"} not resolved or deferred. Finish those items in Rule Lab and export again.`);
      const invalidComponents: string[] = [];
      for (const [id, decision] of decisions) {
        for (const component of decision.components || []) {
          const wohRow = findWohByReference(rows, component.wohSku);
          const sourcing = wohRow ? wohMakeBuy(wohRow) : "Not set";
          if (!wohRow || !component.quantity || !["Not set", "Buy", "Local"].includes(sourcing))
            invalidComponents.push(`${id}: ${component.wohSku || "missing WOH SKU"} (${wohRow ? sourcing : "not found"})`);
        }
      }
      if (invalidComponents.length)
        throw new Error(`Import blocked: ${invalidComponents.length} component mapping${invalidComponents.length === 1 ? " is" : "s are"} missing, zero-quantity, or not eligible (blank/Buy/Local only). First issue: ${invalidComponents[0]}.`);
      const byKey = new Map(ebayMappings.map((item) => [item.key, item]));
      const byListingSku = new Map(ebayMappings.map((item) => [`${item.listingId}:${cleanSku(item.sku || item.listingSku)}`, item]));
      const nextByKey = new Map(ebayMappings.map((item) => [item.key, item]));
      const unmatched: string[] = [];
      for (const [id, decision] of decisions) {
        const source = sourceById.get(id);
        if (!source) { unmatched.push(id); continue; }
        const current = (source.listingKey && byKey.get(source.listingKey)) || byListingSku.get(`${source.listingId || ""}:${cleanSku(source.sourceSku)}`);
        if (!current) { unmatched.push(`${id} (${source.sourceSku})`); continue; }
        const directRow = decision.wohSku ? findWohByReference(rows, decision.wohSku) : null;
        const isAssembly = isAssemblyWorkflowStatus(decision.status);
        nextByKey.set(current.key, {
          ...current,
          wohSku: directRow ? wohMappingSku(directRow) : "",
          wohDescription: directRow?.description || "",
          matchStatus: directRow ? "Exact" : isAssembly ? "Manual" : "Unmatched",
          workflowStatus: decision.status,
          assembly: isAssembly,
          assemblyConfirmed: isAssembly,
          assemblyComponents: isAssembly ? decision.components || [] : [],
          deferred: decision.status === "Deferred",
          decisionLocked: true,
          knowledgeSource: `${decision.source} · imported ${payload.exportedAt || new Date().toISOString()}`,
        });
      }
      if (unmatched.length)
        throw new Error(`${unmatched.length} completed decision${unmatched.length === 1 ? " does" : "s do"} not match the currently loaded eBay catalog. First mismatch: ${unmatched[0]}.`);
      const nextMappings = [...nextByKey.values()];
      const changed = nextMappings.filter((mapping) => decisions.has(payload.sourceItems?.find((source) => source.listingKey === mapping.key)?.id || ""));
      setRuleLabImportMessage(`Saving ${changed.length.toLocaleString()} locked decisions to StockLens…`);
      for (let offset = 0; offset < changed.length; offset += 20) {
        const batch = changed.slice(offset, offset + 20);
        await Promise.all(batch.map(async (mapping) => {
          const response = await fetch("/api/ebay/mappings", {
            method: "POST",
            headers: { "content-type": "application/json", "x-stocklens-admin-key": ebayAdminKey },
            body: JSON.stringify({ listingKey: mapping.key, listingId: mapping.listingId, ebaySku: mapping.sku || mapping.listingSku, wohSku: mapping.wohSku, workflowStatus: mapping.workflowStatus, assemblyConfirmed: mapping.assemblyConfirmed, assemblyComponents: mapping.assemblyComponents, assemblyLaborCost: mapping.assemblyLaborCost ?? 2, knowledgeSource: mapping.knowledgeSource, decisionLocked: true, changeSource: "user", sessionId: ebaySession.id }),
          });
          const data = await response.json().catch(() => null) as { error?: string } | null;
          if (!response.ok) throw new Error(data?.error || `${mapping.sku || mapping.listingSku} could not be saved`);
        }));
        setRuleLabImportMessage(`Saved ${Math.min(offset + batch.length, changed.length).toLocaleString()} of ${changed.length.toLocaleString()} decisions…`);
      }
      setEbayMappings(nextMappings);
      ebayMappingsRef.current = nextMappings;
      const token = await getAccessToken();
      const historyResponse = await fetch("/api/ebay/mapping-history", { cache: "no-store", headers: { "x-stocklens-admin-key": ebayAdminKey } });
      const history = await historyResponse.json().catch(() => null) as { changes?: EbayMappingHistory[]; error?: string } | null;
      if (!historyResponse.ok) throw new Error(history?.error || "Updated mapping history could not be loaded");
      const master = await syncEbayMappingDriveFiles(token, nextMappings, history?.changes || [], payload.exportedAt || ebayImportedAt || new Date().toISOString());
      setRuleLabImportMessage(`${changed.length.toLocaleString()} Rule Lab decisions imported. eBay and shared channel masters updated · ${new Date(master.versionDate).toLocaleString()}.`);
      setNotice("Completed Rule Lab review imported and all mapping masters synchronized");
    } catch (error) {
      setRuleLabImportMessage(error instanceof Error ? error.message : "The Rule Lab export could not be imported");
    } finally {
      setRuleLabImporting(false);
      if (ruleLabImportInputRef.current) ruleLabImportInputRef.current.value = "";
    }
  }
  async function checkMappingCompatibility() {
    setMappingCompatibilityChecking(true);
    setMappingCompatibilityResults([]);
    try {
      const token = await getAccessToken();
      const master = await loadChannelMappingMasterRows(token);
      const results: MappingCompatibilityResult[] = [];
      const channels = [{ label: "eBay", count: master.ebayMappings.length }, { label: "Shopify", count: master.shopifyMappings.length }, { label: "Amazon", count: master.amazonMappings.length }];
      for (const channel of channels) results.push({ label: `${channel.label} mapper`, status: channel.count ? "Pass" : "Warning", detail: channel.count ? `${channel.count.toLocaleString()} records parse correctly from the shared master.` : "No saved records yet; the mapper can create the first records." });
      const all = [...master.ebayMappings, ...master.shopifyMappings, ...master.amazonMappings];
      const incompleteAssemblies = all.filter((item) => isAssemblyWorkflowStatus(item.workflowStatus) && (!item.assemblyComponents.length || item.assemblyComponents.some((component) => !component.wohSku || component.quantity <= 0)));
      results.push({ label: "Assembly consumers", status: incompleteAssemblies.length ? "Fail" : "Pass", detail: incompleteAssemblies.length ? `${incompleteAssemblies.length.toLocaleString()} assembly records have missing WOH components or quantities.` : "Every saved assembly has component-level WOH SKUs and positive fractional-compatible quantities." });
      const translation = buildChannelTranslationRows(master.ebayMappings, master.shopifyMappings, master.amazonMappings);
      results.push({ label: "Inventory sync, Item Lookup, ABC, ShipStation", status: translation.length ? "Pass" : "Fail", detail: `${translation.length.toLocaleString()} normalized WOH/assembly identities rebuild successfully for downstream tools.` });
      results.push({ label: "Master version", status: master.versionDate ? "Pass" : "Warning", detail: master.versionDate ? `Shared master version ${new Date(master.versionDate).toLocaleString()}.` : "Version metadata is missing." });
      setMappingCompatibilityResults(results);
    } catch (error) {
      setMappingCompatibilityResults([{ label: "Shared mapping master", status: "Fail", detail: error instanceof Error ? error.message : "Compatibility check failed" }]);
    } finally { setMappingCompatibilityChecking(false); }
  }
