  async function loadEbayAbcListingCandidates(token: string) {
    const file = await findDriveFileInFolder(token, WOH_FOLDER_ID, EBAY_ABC_MASTER_NAME);
    if (!file) return [] as EbayListing[];
    const buffer = await downloadDriveFile(token, file.id, `${EBAY_ABC_MASTER_NAME} could not be opened`);
    const workbook = XLSX.read(buffer, { type: "array" });
    const candidates = new Map<string, EbayListing>();
    const candidateKeysBySku = new Map<string, Set<string>>();
    const addCandidate = (listingIdValue: unknown, skuValue: unknown, titleValue: unknown, unitsValue: unknown, sourceSheet: string) => {
      const listingId = String(listingIdValue || "").trim();
      const sku = String(skuValue || "").trim();
      if (!listingId && !sku) return;
      const normalizedSku = cleanSku(sku);
      if (!normalizedSku && !listingId) return;
      const key = `${listingId}:${normalizedSku}`;
      const existing = candidates.get(key);
      const title = String(titleValue || "").trim();
      if (existing) {
        if (!existing.title && title) candidates.set(key, { ...existing, title });
        return;
      }
      // A SKU-only exception row is useful only when no listing-specific row
      // exists elsewhere in the permanent ABC workbook.
      if (!listingId && candidateKeysBySku.get(normalizedSku)?.size) return;
      if (listingId) {
        const skuOnlyKey = `:${normalizedSku}`;
        if (candidates.has(skuOnlyKey)) candidates.delete(skuOnlyKey);
      }
      candidates.set(key, {
        listingId,
        title,
        listingSku: sku,
        sku,
        variation: "",
        price: 0,
        currency: "USD",
        quantityAvailable: 0,
        quantitySold: spreadsheetNumber(unitsValue),
        listingType: `ABC history · ${sourceSheet}`,
        status: "Historical · ABC analysis",
        upc: "",
      });
      const keys = candidateKeysBySku.get(normalizedSku) || new Set<string>();
      keys.add(key); candidateKeysBySku.set(normalizedSku, keys);
    };
    for (const sheetName of workbook.SheetNames) {
      const sheet = workbook.Sheets[sheetName];
      if (!sheet) continue;
      const rows = XLSX.utils.sheet_to_json<Record<string, unknown>>(sheet, { defval: "", raw: false });
      if (/^eBay ABC \d+ Months$/i.test(sheetName) || sheetName === "Calculation Trace" || sheetName === "Order Calculation Trace") {
        for (const row of rows) addCandidate(row["eBay Listing ID"], row["eBay SKU"], row.Title, row.Units || row.Quantity, sheetName);
      } else if (sheetName === "Component Where Used") {
        for (const row of rows) addCandidate(row["Parent eBay Listing ID"], row["Parent eBay SKU"], row["Parent Title"], row["Parent Units Sold"], sheetName);
      } else if (sheetName === "Undetermined Reasons") {
        for (const row of rows) addCandidate("", row["eBay SKU"], row.Title, row.Units, sheetName);
      }
    }
    return [...candidates.values()];
  }
