    const totalPositive = positive.reduce((sum, item) => sum + item.profit, 0);
    let cumulative = 0;
    for (const item of positive) { const before = totalPositive ? cumulative / totalPositive : 1; item.slItemClass = before < .5 ? "AA" : before < .8 ? "A" : before < .9 ? "B" : before < .98 ? "C" : "D"; cumulative += item.profit; item.cumulativeProfitPercent = totalPositive ? cumulative / totalPositive * 100 : 100; }
    for (const item of determined.filter((candidate) => candidate.profit < 0)) item.slItemClass = "E";
