      if (ebayShippingPendingRef.current) ebayShippingPendingRef.current.cache = cache;
      const mergedDrafts = { ...ebayShippingRateDrafts };
      for (const [key, imported] of Object.entries(importedDrafts)) {
        const saved = mergedDrafts[key] || { one: "", two: "", four: "" };
        mergedDrafts[key] = { one: imported.one ?? saved.one, two: imported.two ?? saved.two, four: imported.four ?? saved.four };
      }
      setEbayShippingRateDrafts((current) => {
        const next = { ...current };
        for (const [key, imported] of Object.entries(importedDrafts)) {
          const saved = next[key] || { one: "", two: "", four: "" };
          next[key] = { one: imported.one ?? saved.one, two: imported.two ?? saved.two, four: imported.four ?? saved.four };
        }
        return next;
      });
      const remainingRequested = ebayShippingRateReview.filter((rate) => {
        const draft = mergedDrafts[cleanSku(rate.wohSku)] || { one: "", two: "", four: "" };
        return rate.requiredBands.some((band) => spreadsheetNumber(band === 1 ? draft.one : band === 2 ? draft.two : draft.four) <= 0);
      });
